 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])

    # The color key is a short repeated stripe. Read its varying color sequence
    # from identical adjacent rows (the stripe may be horizontal).
    key = None
    for r in range(h - 1):
        if grid[r] == grid[r + 1] and any(grid[r]):
            end = r + 1
            while end + 1 < h and grid[end + 1] == grid[r]:
                end += 1
            vals = [v for v in grid[r] if v]
            if len(vals) >= 2 and (key is None or len(vals) > len(key)):
                key = vals
    if key is None:
        # Also support a stripe repeated across adjacent columns.
        for c in range(w - 1):
            col = [grid[r][c] for r in range(h)]
            if col == [grid[r][c + 1] for r in range(h)] and any(col):
                vals = [v for v in col if v]
                if len(vals) >= 2 and (key is None or len(vals) > len(key)):
                    key = vals
    if key is None or 1 not in key:
        return [row[:] for row in grid]

    # Locate the largest four-connected component of color 1; this is the
    # motif to replicate, rather than the small color-1 mark in the key.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            components.append(comp)
    if not components:
        return [row[:] for row in grid]
    motif = max(components, key=len)
    top = min(r for r, c in motif)
    left = min(c for r, c in motif)
    bottom = max(r for r, c in motif)
    height = bottom - top + 1
    one_index = key.index(1)

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(key):
        dr = top + (i - one_index) * height
        for r, c in motif:
            rr = dr + (r - top)
            cc = left + (c - left)
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
